<?php require_once __DIR__ . '/../config/auth.php'; requireLogin(); checkBlocked(); updateLastActivity(); header('Content-Type: application/json; charset=UTF-8'); /* * Текущий пользователь. */ $user = currentUser(); if (!$user) { http_response_code(401); echo json_encode( array( 'success' => false, 'error' => 'Пользователь не авторизован.' ), JSON_UNESCAPED_UNICODE ); exit; } $currentUserId = (int) $user['id']; /* * ID собеседника. * * Можно передать: * * ?receiver_id=5 */ $receiverId = isset($_GET['receiver_id']) ? (int) $_GET['receiver_id'] : 0; /* * Проверяем ID. */ if ($receiverId <= 0) { http_response_code(400); echo json_encode( array( 'success' => false, 'error' => 'Не указан пользователь диалога.' ), JSON_UNESCAPED_UNICODE ); exit; } /* * Нельзя открыть приватный диалог * с самим собой. */ if ($receiverId === $currentUserId) { http_response_code(400); echo json_encode( array( 'success' => false, 'error' => 'Нельзя открыть диалог с самим собой.' ), JSON_UNESCAPED_UNICODE ); exit; } /* * Проверяем существование собеседника. */ $stmt = $pdo->prepare( 'SELECT id, username, is_blocked FROM users WHERE id = ? LIMIT 1' ); $stmt->execute( array( $receiverId ) ); $receiver = $stmt->fetch(); if (!$receiver) { http_response_code(404); echo json_encode( array( 'success' => false, 'error' => 'Пользователь не найден.' ), JSON_UNESCAPED_UNICODE ); exit; } /* * Если пользователь заблокирован — * диалог недоступен. */ if ( isset($receiver['is_blocked']) && (int) $receiver['is_blocked'] === 1 ) { http_response_code(403); echo json_encode( array( 'success' => false, 'error' => 'Этот пользователь заблокирован.' ), JSON_UNESCAPED_UNICODE ); exit; } /* * Загружаем сообщения только между * текущим пользователем и собеседником. * * Важный момент: * * ( * user_id = текущий * AND receiver_id = собеседник * ) * * OR * * ( * user_id = собеседник * AND receiver_id = текущий * ) * * Поэтому чужие приватные диалоги * сюда попасть не могут. */ $stmt = $pdo->prepare( 'SELECT m.id, m.user_id, m.receiver_id, m.message, m.created_at, u.username FROM messages m INNER JOIN users u ON u.id = m.user_id WHERE ( m.user_id = ? AND m.receiver_id = ? ) OR ( m.user_id = ? AND m.receiver_id = ? ) ORDER BY m.id ASC LIMIT 200' ); $stmt->execute( array( $currentUserId, $receiverId, $receiverId, $currentUserId ) ); $messages = $stmt->fetchAll(); /* * Формируем JSON. */ $result = array(); foreach ($messages as $message) { $result[] = array( 'id' => (int) $message['id'], 'user_id' => (int) $message['user_id'], 'receiver_id' => (int) $message['receiver_id'], 'username' => $message['username'], 'message' => $message['message'], 'created_at' => $message['created_at'], 'mine' => ( (int) $message['user_id'] === $currentUserId ) ); } /* * Возвращаем данные. */ echo json_encode( array( 'success' => true, 'current_user_id' => $currentUserId, 'receiver_id' => $receiverId, 'receiver_username' => $receiver['username'], 'messages' => $result ), JSON_UNESCAPED_UNICODE ); exit; ?>